-- =============================================================================
-- 하루정리 — 한자 111~3000번째 2,890자 추가 (총 3,000자, 2026-11-04 사용자 요청)
-- 순서(sort_order 111~3000):
--   1) 천자문 나머지 (111~1000)          — 원문·구절 풀이: 위키문헌 '번역:천자문'(CC BY-SA 4.0), 원문은 공유 저작물
--   2) 한문 교육용 기초 한자 중 천자문에 없는 글자 (1001~2031) — 중학교용 → 고등학교용 (교육부 고시)
--   3) 자주 쓰이는 한자 (2032~3000)        — KS X 1001 수록 한자 중 Unicode Unihan 학년 등급·핵심 한자 순
-- 훈: 위키낱말사전 '부록:한문 교육용 기초 한자 1800'과 각 한자 문서(CC BY-SA 4.0). 문서가 없는 천자문 63자는 전통 천자문 훈으로 작성.
-- 음: 모든 글자를 Unicode Unihan(kHangul)과 대조. 두음 법칙 형태는 본음으로 저장(예: 렬, 려).
-- 한자마다 4지선다 문제 정확히 1개(음 또는 뜻). 단어·예문은 넣지 않음(화면에 '관련 단어 없음' 표시).
-- 재실행해도 중복되지 않음. 기존 110자·사용자 기록은 바꾸지 않음. 이 파일은 데이터 목록에서 생성함.
-- =============================================================================

